import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { format, parseISO } from 'date-fns';
import { Button, Checkbox, Input, Select, dispatchAppToast } from '@linm-soft-org/linm-web-common-components';
import {
  deleteWeighTicket,
  listWeighTickets,
  type WeighTicketFilterQuery,
  type WeighTicketListItem,
} from '../../../services/weighTickets/endpoint';
import { useAppDispatch } from '../../../store/hooks';
import df from '../../../styles/documentForm.module.css';

type SearchState = {
  ngayCt1: string;
  ngayCt2: string;
  soCt1: string;
  soCt2: string;
  maKh: string;
  maVt: string;
  maXe: string;
  lenhSo: string;
  loaiCan: string;
  maGd: string;
  dienGiai: string;
  maPost: string;
  locNsd: boolean;
};

const EMPTY_SEARCH: SearchState = {
  ngayCt1: '',
  ngayCt2: '',
  soCt1: '',
  soCt2: '',
  maKh: '',
  maVt: '',
  maXe: '',
  lenhSo: '',
  loaiCan: '',
  maGd: '',
  dienGiai: '',
  maPost: '9',
  locNsd: false,
};

function todayLocal(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function showDate(value: string | null | undefined): string {
  if (!value) return '';
  const parsed = parseISO(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return format(parsed, 'dd/MM/yyyy');
}

function showMoney(value: number | null | undefined): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value ?? 0);
}

function tightenDates(state: SearchState): SearchState {
  const next = { ...state };
  if (!next.ngayCt1 && !next.ngayCt2) {
    const today = todayLocal();
    next.ngayCt1 = today;
    next.ngayCt2 = today;
  } else if (!next.ngayCt1) {
    next.ngayCt1 = next.ngayCt2;
  } else if (!next.ngayCt2) {
    next.ngayCt2 = next.ngayCt1;
  }
  return next;
}

function toQuery(state: SearchState): WeighTicketFilterQuery {
  const query: WeighTicketFilterQuery = {
    ngayCt1: state.ngayCt1,
    ngayCt2: state.ngayCt2,
    maPost: state.maPost === '3' ? '3' : '9',
  };
  (['soCt1', 'soCt2', 'maKh', 'maVt', 'maXe', 'lenhSo', 'dienGiai'] as const).forEach(key => {
    const value = state[key].trim();
    if (value) query[key] = value;
  });
  if (state.loaiCan === '1' || state.loaiCan === '2') query.loaiCan = state.loaiCan;
  if (state.maGd === '1' || state.maGd === '2') query.maGd = state.maGd;
  if (state.locNsd) query.locNsd = true;
  return query;
}

function rowStyle(row: WeighTicketListItem, selected: boolean): React.CSSProperties {
  let background: string | undefined;
  const pointer = (row.sttRecCanBi ?? '').trim();
  if (row.loaiCan === '1' && pointer.length === 0) background = 'YELLOW';
  else if (row.loaiCan === '1' && pointer.length > 0) background = 'Pink';
  else if (row.loaiCan === '2' && row.maPost < '9') background = 'Cyan';
  if (selected && background) {
    return { background, boxShadow: 'inset 0 0 0 2px var(--ds-color-primary, #0d6efd)' };
  }
  if (selected) return { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' };
  return background ? { background } : {};
}

const Pw1ListPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const [search, setSearch] = useState<SearchState>(EMPTY_SEARCH);
  const [items, setItems] = useState<WeighTicketListItem[]>([]);
  const [filtering, setFiltering] = useState(false);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const patch = (next: Partial<SearchState>) => setSearch(prev => ({ ...prev, ...next }));

  const applyRows = (rows: WeighTicketListItem[]) => {
    setItems(rows);
    setSelectedSttRec(prev => (rows.some(row => row.sttRec === prev) ? prev : ''));
  };

  const loadEmpty = async () => {
    setError('');
    setLoading(true);
    try {
      applyRows(await listWeighTickets({}));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách phiếu cân hàng');
    } finally {
      setLoading(false);
    }
  };

  const runSearch = async (state: SearchState) => {
    const tightened = tightenDates(state);
    setSearch(tightened);
    setFiltering(true);
    setError('');
    setLoading(true);
    try {
      applyRows(await listWeighTickets(toQuery(tightened)));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách phiếu cân hàng');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadEmpty();
  }, []);

  const onSearch = () => {
    void runSearch(search);
  };

  const onRefresh = () => {
    if (!filtering) {
      void loadEmpty();
      return;
    }
    void runSearch(search);
  };

  const onDelete = async () => {
    if (!selectedSttRec || deleting) return;
    setDeleting(true);
    setError('');
    try {
      await deleteWeighTicket(selectedSttRec);
      dispatchAppToast(dispatch, { message: 'Đã xóa phiếu cân hàng', type: 'success' });
      setSelectedSttRec('');
      if (filtering) await runSearch(search);
      else await loadEmpty();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Xóa thất bại');
    } finally {
      setDeleting(false);
    }
  };

  const onEnter = (event: React.KeyboardEvent<HTMLElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      onSearch();
    }
  };

  const noSelection = !selectedSttRec;
  const emptyText = filtering ? 'Không tìm thấy phiếu cân hàng' : 'Không có phiếu cân hàng';

  return (
    <div className={df.page} data-testid="ct-pw1-list">
      <h1 data-testid="ct-pw1-title">Phiếu cân hàng</h1>
      <div>
        <Button variant="secondary" data-testid="ct-pw1-toolbar-refresh-btn" onClick={onRefresh} loading={loading}>
          Làm mới
        </Button>
        <Button variant="primary" data-testid="ct-pw1-toolbar-add-btn" onClick={() => navigate('/bh/pw1/them')}>
          Thêm
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-pw1-toolbar-edit-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/pw1/${encodeURIComponent(selectedSttRec)}`)}
        >
          Sửa
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-pw1-toolbar-view-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/pw1/${encodeURIComponent(selectedSttRec)}?mode=view`)}
        >
          Xem
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-pw1-toolbar-copy-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/pw1/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}
        >
          Sao chép
        </Button>
        <Button
          variant="danger"
          data-testid="ct-pw1-toolbar-delete-btn"
          disabled={noSelection || deleting}
          loading={deleting}
          onClick={() => { void onDelete(); }}
        >
          Xóa
        </Button>
      </div>

      <section className={df.section} data-testid="ct-pw1-search" onKeyDown={onEnter}>
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Ngày từ</label>
            <Input type="date" data-testid="ct-pw1-search-ngayCt1" value={search.ngayCt1} onChange={e => patch({ ngayCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Ngày đến</label>
            <Input type="date" data-testid="ct-pw1-search-ngayCt2" value={search.ngayCt2} onChange={e => patch({ ngayCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số C.từ từ</label>
            <Input data-testid="ct-pw1-search-soCt1" value={search.soCt1} onChange={e => patch({ soCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số C.từ đến</label>
            <Input data-testid="ct-pw1-search-soCt2" value={search.soCt2} onChange={e => patch({ soCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Mã khách hàng</label>
            <Input data-testid="ct-pw1-search-maKh" value={search.maKh} onChange={e => patch({ maKh: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Mã Hàng</label>
            <Input data-testid="ct-pw1-search-maVt" value={search.maVt} onChange={e => patch({ maVt: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Biển số</label>
            <Input data-testid="ct-pw1-search-maXe" value={search.maXe} onChange={e => patch({ maXe: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số lệnh</label>
            <Input data-testid="ct-pw1-search-lenhSo" value={search.lenhSo} onChange={e => patch({ lenhSo: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Loại cân</label>
            <Select
              data-testid="ct-pw1-search-loaiCan"
              value={search.loaiCan}
              onChange={e => patch({ loaiCan: e.target.value })}
              options={[
                { value: '', label: 'Tất cả' },
                { value: '1', label: 'Cân xe vào' },
                { value: '2', label: 'Cân xe ra' },
              ]}
            />
          </div>
          <div className={df.field}>
            <label className={df.label}>Loại giao dịch</label>
            <Select
              data-testid="ct-pw1-search-maGd"
              value={search.maGd}
              onChange={e => patch({ maGd: e.target.value })}
              options={[
                { value: '', label: 'Tất cả' },
                { value: '1', label: 'Cân xuất' },
                { value: '2', label: 'Cân nhập' },
              ]}
            />
          </div>
          <div className={`${df.field} ${df.spanCol2}`}>
            <label className={df.label}>Diễn giải</label>
            <Input data-testid="ct-pw1-search-dienGiai" value={search.dienGiai} onChange={e => patch({ dienGiai: e.target.value })} />
          </div>
        </div>
        <Button variant="primary" data-testid="ct-pw1-search-btn" onClick={onSearch} loading={loading}>
          Tìm
        </Button>
      </section>

      <section className={df.section} data-testid="ct-pw1-search-extra" onKeyDown={onEnter}>
        <h2 className={df.sectionTitle}>Điều kiện thêm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Trạng thái</label>
            <Select
              data-testid="ct-pw1-search-maPost"
              value={search.maPost}
              onChange={e => patch({ maPost: e.target.value })}
              options={[
                { value: '3', label: 'Lập phiếu cân' },
                { value: '9', label: 'Đã kiểm duyệt phiếu' },
              ]}
            />
          </div>
          <div className={df.field}>
            <Checkbox
              label="Chỉ chứng từ của tôi"
              data-testid="ct-pw1-search-locNsd"
              checked={search.locNsd}
              onChange={e => patch({ locNsd: e.target.checked })}
            />
          </div>
        </div>
      </section>

      {error ? <div className={df.errorBanner}>{error}</div> : null}
      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-pw1-grid">
          <thead>
            <tr>
              <th>Số C.từ</th>
              <th>Ngày C.từ</th>
              <th>Mã khách hàng</th>
              <th>Tên khách hàng</th>
              <th>Biển số</th>
              <th>Tên Hàng</th>
              <th>Mã Hàng</th>
              <th>KL trên cân</th>
              <th>KL bì xe</th>
              <th>KL hàng</th>
              <th>Tiền thuế</th>
              <th>Tiền hàng</th>
              <th>Tổng cộng</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => (
              <tr
                key={row.sttRec}
                aria-selected={row.sttRec === selectedSttRec}
                style={rowStyle(row, row.sttRec === selectedSttRec)}
                onClick={() => setSelectedSttRec(row.sttRec)}
              >
                <td>{row.soCt}</td>
                <td>{showDate(row.ngayCt)}</td>
                <td>{row.maKh}</td>
                <td>{row.tenKh}</td>
                <td>{row.maXe}</td>
                <td>{row.tenVt}</td>
                <td>{row.maVt}</td>
                <td>{showMoney(row.klCan)}</td>
                <td>{showMoney(row.klBi)}</td>
                <td>{showMoney(row.klHang)}</td>
                <td>{showMoney(row.thueNt)}</td>
                <td>{showMoney(row.tTienNt2)}</td>
                <td>{showMoney(row.tTtNt)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {items.length === 0 ? <div>{emptyText}</div> : null}
    </div>
  );
};

export default Pw1ListPage;
